// Applies the SQL migrations generated by drizzle-kit (./drizzle) with drizzle's own migrator.
// Called automatically by src/db/index.ts the first time the database is opened in a process
// (and therefore on server start via src/instrumentation.ts).
import path from "node:path";
import { migrate } from "drizzle-orm/better-sqlite3/migrator";
import type { DB } from "./index";

/** Folder holding drizzle-kit output (`drizzle/*.sql` + `drizzle/meta`). Must ship next to the server (Docker: /app/drizzle). */
export function migrationsFolder(): string {
  return path.join(process.cwd(), "drizzle");
}

function sleepSync(ms: number) {
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
}

/**
 * Run pending migrations. drizzle's sqlite migrator reads the applied state *before* opening its transaction, so two
 * processes booting at the same time (e.g. build workers) can race on the very first migration: the loser fails with
 * "table already exists" once the winner commits. A short retry sees the committed state and becomes a no-op.
 */
export function applyMigrations(db: DB): void {
  const folder = migrationsFolder();
  for (let attempt = 1; ; attempt++) {
    try {
      migrate(db, { migrationsFolder: folder });
      return;
    } catch (err) {
      if (attempt >= 4) throw err;
      sleepSync(150 * attempt);
    }
  }
}
